/**
 * Sitemap tip kayıt tablosu (registry).
 *
 * Üst index ve leaf route'lar yalnızca buradan beslenir. Yeni bir tür eklemek
 * (museums, museum-categories, attractions, blog, suppliers…) = bu listeye bir
 * `SitemapType` eklemek. Veri apiv3'ten ham gelir (slug/url + lastmod); URL'leri
 * burada kurarız (URL yapısının sahibi front-end'dir).
 */

export const SITE_URL = "https://travelshopbooking.com";

const APIV3_URL = process.env.NEXT_PUBLIC_APIV3_URL;
const APP_TOKEN = process.env.APIV3_APP_TOKEN ?? "";

/** Tüm leaf sitemap route'larının ortak yeniden doğrulama süresi (saniye). */
export const SITEMAP_REVALIDATE = 86400;

export type Changefreq =
  | "always"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly"
  | "yearly"
  | "never";

export interface SitemapEntry {
  /** Site köküne göre yol, örn. "/tour/foo" veya "/europe-tours". */
  loc: string;
  /** W3C/ISO datetime; yoksa atlanır. */
  lastmod?: string;
  /** Sayfaya özel override; yoksa türün değeri kullanılır. (Google bunları
   *  pratikte yok sayar; yine de tutarlılık için.) */
  changefreq?: Changefreq;
  priority?: number;
}

export interface SitemapType {
  /** URL ve dosya adında kullanılan anahtar: "tours", "tour-categories". */
  key: string;
  /**
   * Tek dosyalık (chunk'sız) tür. true ise leaf adı düz "{key}.xml" olur
   * (örn. main.xml), index'te chunk hesaplanmaz. Sayısı her zaman düşük/sabit
   * türler için (anasayfa + sabit sayfalar gibi).
   */
  singleFile?: boolean;
  /** Tek leaf dosyadaki maksimum URL (sitemaps.org limiti 50.000). */
  chunkSize: number;
  changefreq: Changefreq;
  priority: number;
  /** Toplam yayındaki kayıt sayısı — index, chunk sayısını bununla hesaplar. */
  count(): Promise<number>;
  /** Verilen 0-tabanlı chunk indeksinin URL'leri. */
  chunk(index: number): Promise<SitemapEntry[]>;
}

async function apiv3<T>(path: string): Promise<T> {
  const res = await fetch(`${APIV3_URL}${path}`, {
    method: "GET",
    headers: {
      Accept: "application/json",
      "Content-Language": "en",
      "Content-type": "application/json",
      "X-App-Token": APP_TOKEN,
    },
    next: { revalidate: SITEMAP_REVALIDATE },
  });

  if (!res.ok) {
    throw new Error(`Sitemap apiv3 fetch failed: ${path} (${res.status})`);
  }

  return res.json() as Promise<T>;
}

type SlugItem = { slug: string; lastmod: string | null };
type CategoryItem = { pageUrl: string; lastmod: string | null };

/**
 * apiv3'in ortak sayfalı slug sözleşmesini (?page&per → {total, items:[{slug,
 * lastmod}]}) tüketen tür üreticisi. Yeni "slug listesi" türü = bir çağrı.
 * `toLoc` slug'ı front-end URL'ine çevirir (URL yapısının sahibi burası).
 */
function paginatedApiType(opts: {
  key: string;
  endpoint: string;
  toLoc: (slug: string) => string;
  chunkSize: number;
  changefreq: Changefreq;
  priority: number;
}): SitemapType {
  return {
    key: opts.key,
    chunkSize: opts.chunkSize,
    changefreq: opts.changefreq,
    priority: opts.priority,
    async count() {
      const data = await apiv3<{ total: number }>(
        `/sitemap/${opts.endpoint}?page=1&per=1`,
      );
      return data.total;
    },
    async chunk(index) {
      const data = await apiv3<{ items: SlugItem[] }>(
        `/sitemap/${opts.endpoint}?page=${index + 1}&per=${opts.chunkSize}`,
      );
      return data.items.map((it) => ({
        loc: opts.toLoc(it.slug),
        lastmod: it.lastmod ?? undefined,
      }));
    },
  };
}

const CHUNK = 5000;

const tours = paginatedApiType({
  key: "tours",
  endpoint: "tours",
  toLoc: (s) => `/tour/${s}`,
  chunkSize: CHUNK,
  changefreq: "weekly",
  priority: 1.0,
});

const attractions = paginatedApiType({
  key: "attractions",
  endpoint: "attractions",
  toLoc: (s) => `/attractions/${s}`,
  chunkSize: CHUNK,
  changefreq: "weekly",
  priority: 0.7,
});

const museums = paginatedApiType({
  key: "museums",
  endpoint: "museums",
  toLoc: (s) => `/museum/${s}`, // detay route'u tekil: /museum/[slug]
  chunkSize: CHUNK,
  changefreq: "weekly",
  priority: 0.7,
});

const blog = paginatedApiType({
  key: "blog",
  endpoint: "blog",
  toLoc: (s) => `/blog/${s}`,
  chunkSize: CHUNK,
  changefreq: "weekly",
  priority: 0.6,
});

/** Tur kategori sayfaları → /{pageUrl} (kök altında). Tek dosyaya sığar. */
const tourCategories: SitemapType = {
  key: "tour-categories",
  chunkSize: 50000,
  changefreq: "weekly",
  priority: 0.9,
  async count() {
    const data = await apiv3<{ total: number }>(`/sitemap/tour-categories`);
    return data.total;
  },
  async chunk() {
    const data = await apiv3<{ items: CategoryItem[] }>(`/sitemap/tour-categories`);
    return data.items.map((c) => ({
      loc: `/${c.pageUrl}`,
      lastmod: c.lastmod ?? undefined,
    }));
  },
};

/**
 * Ana (merkezi) sayfalar — API gerektirmez. Anasayfa + dahil edilecek sabit
 * sayfalar. Tek dosya (main.xml), chunk'sız. Yeni sabit sayfa = bu diziye bir
 * satır (loc kök göreli, baş "/" ile).
 * TODO: kullanıcının vereceği nihai liste ile genişletilecek.
 */
const MAIN_PAGES: SitemapEntry[] = [
  { loc: "/", changefreq: "weekly", priority: 1.0 },
  { loc: "/about-us" },
  { loc: "/attractions", changefreq: "weekly" },
  { loc: "/awards" },
  { loc: "/black-friday-travel-deals", changefreq: "weekly" },
  { loc: "/blog", changefreq: "weekly" },
  { loc: "/deals", changefreq: "weekly" },
  { loc: "/legal-disclaimer", changefreq: "yearly" },
  { loc: "/museums", changefreq: "weekly" },
  { loc: "/terms-of-use", changefreq: "yearly" },
  { loc: "/cancellation-policy", changefreq: "yearly" },
  { loc: "/careers" },
  { loc: "/contact-us" },
  { loc: "/credit-terms", changefreq: "yearly" },
  { loc: "/help-center" },
  { loc: "/privacy-policy", changefreq: "yearly" },
  { loc: "/support" },
];

const main: SitemapType = {
  key: "main",
  singleFile: true,
  chunkSize: 50000,
  changefreq: "monthly",
  priority: 0.8,
  async count() {
    return MAIN_PAGES.length;
  },
  async chunk() {
    return MAIN_PAGES;
  },
};

/** Üst index'in gezeceği sıra. Yeni tür buraya eklenir. */
export const SITEMAP_TYPES: SitemapType[] = [
  main,
  tours,
  attractions,
  museums,
  blog,
  tourCategories,
];

export function getSitemapType(key: string): SitemapType | undefined {
  return SITEMAP_TYPES.find((t) => t.key === key);
}

export function chunkCount(total: number, chunkSize: number): number {
  return Math.max(1, Math.ceil(total / chunkSize));
}
