/**
 * Sitemap XML üreticileri (index + urlset). Bağımlılık yok; düz string render.
 */

import { SITE_URL, type SitemapEntry } from "./registry";

function esc(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function abs(loc: string): string {
  return esc(`${SITE_URL}${loc}`);
}

export interface UrlSetOptions {
  changefreq?: string;
  priority?: number;
}

export function buildUrlSet(entries: SitemapEntry[], opts: UrlSetOptions): string {
  const body = entries
    .map((e) => {
      const changefreq = e.changefreq ?? opts.changefreq;
      const priority = e.priority ?? opts.priority;
      const parts = [`<loc>${abs(e.loc)}</loc>`];
      if (e.lastmod) parts.push(`<lastmod>${esc(e.lastmod)}</lastmod>`);
      if (changefreq) parts.push(`<changefreq>${changefreq}</changefreq>`);
      if (priority != null) parts.push(`<priority>${priority.toFixed(1)}</priority>`);
      return `<url>${parts.join("")}</url>`;
    })
    .join("");

  return `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${body}</urlset>`;
}

export function buildIndex(files: { loc: string; lastmod?: string }[]): string {
  const body = files
    .map((f) => {
      const parts = [`<loc>${abs(f.loc)}</loc>`];
      if (f.lastmod) parts.push(`<lastmod>${esc(f.lastmod)}</lastmod>`);
      return `<sitemap>${parts.join("")}</sitemap>`;
    })
    .join("");

  return `<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${body}</sitemapindex>`;
}
